// TestEveryGitHubFileIsGeneratedOrPinned: every file under the repository's
// .github is generated by schema-test ci or pinned in ci-pins.tsv at its
// content's sha256. The plants, each red by name, run in a tree of their
// own: a pinned file edited by hand, a new workflow that is neither, a pin
// of a file that is gone, a pin of a generated file, and each kind of pin
// line that does not read.
func TestEveryGitHubFileIsGeneratedOrPinned(t *testing.T) {
	t.Parallel()
	sum := func(s string) string { return fmt.Sprintf("%x", sha256.Sum256([]byte(s))) }
	write := func(root, p, s string) {
		t.Helper()
		if err := os.MkdirAll(filepath.Join(root, filepath.Dir(p)), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(filepath.Join(root, p), []byte(s), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	const (
		genPath = ".github/workflows/gen.yml"
		actPath = ".github/actions/a/action.yml"
		oldPath = ".github/workflows/old.yml"
		gen     = "name: generated\n"
		act     = "name: a setup action\n"
		old     = "name: a workflow a later layer generates\n"
	)
	generated := map[string][]byte{genPath: []byte(gen)}
	pinText := "# pins\n" + actPath + "\t" + sum(act) + "\tpinned\n" + oldPath + "\t" + sum(old) + "\tnot-yet-generated\n"
	tree := func() string {
		root := t.TempDir()
		write(root, genPath, gen)
		write(root, actPath, act)
		write(root, oldPath, old)
		return root
	}
	pins, p := readPins([]byte(pinText))
	if len(p) > 0 {
		t.Fatalf("the plant's pins do not read: %v", p)
	}
	if p, err := checkTree(tree(), generated, pins); err != nil || len(p) > 0 {
		t.Fatalf("a clean tree is red: %v %v", p, err)
	}
	for name, c := range map[string]struct {
		plant func(root string) []ciPin
		says  string
	}{
		"a pinned file edited by hand": {func(root string) []ciPin {
			write(root, actPath, act+"      - run: make test-c\n")
			return pins
		}, actPath + ": its content is not what " + ciPinsPath + ":2 pinned: a changed pin is a reviewed change; review it, then update that line to: " + actPath + "\t" + sum(act+"      - run: make test-c\n") + "\tpinned"},
		"a new scheduled workflow": {func(root string) []ciPin {
			write(root, ".github/workflows/schema-lua-nightly-fuzz.yml", "on:\n  schedule:\n    - cron: '1 2 * * *'\n")
			return pins
		}, ".github/workflows/schema-lua-nightly-fuzz.yml: neither generated by schema-test ci nor pinned"},
		"a pin of a file that is gone": {func(root string) []ciPin {
			if err := os.Remove(filepath.Join(root, oldPath)); err != nil {
				t.Fatal(err)
			}
			return pins
		}, ciPinsPath + ":3: pins " + oldPath + ", which is not there: delete the line"},
		"a not-yet-generated workflow edited by hand": {func(root string) []ciPin {
			write(root, oldPath, old+"      - run: make test-c\n")
			return pins
		}, oldPath + ": its content is not what " + ciPinsPath + ":3 pinned"},
		"a test workflow pinned as pinned": {func(root string) []ciPin {
			write(root, ".github/workflows/sneaky.yml", "on:\n  schedule:\n    - cron: '1 2 * * *'\n")
			return append(append([]ciPin{}, pins...), ciPin{Path: ".github/workflows/sneaky.yml", Sum: sum("on:\n  schedule:\n    - cron: '1 2 * * *'\n"), State: pinPinned, Line: 4})
		}, ciPinsPath + ":4: pins the workflow .github/workflows/sneaky.yml, which is none of the workflows that run no test"},
		"a not-yet-generated workflow renamed to pinned": {func(root string) []ciPin {
			if err := os.Rename(filepath.Join(root, oldPath), filepath.Join(root, ".github/workflows/old2.yml")); err != nil {
				t.Fatal(err)
			}
			return []ciPin{pins[0], {Path: ".github/workflows/old2.yml", Sum: sum(old), State: pinPinned, Line: 3}}
		}, ciPinsPath + ":3: pins the workflow .github/workflows/old2.yml, which is none of the workflows that run no test"},
		"a not-yet-generated file that is no workflow": {func(root string) []ciPin {
			return []ciPin{{Path: actPath, Sum: sum(act), State: pinNotYetGenerated, Line: 2}, pins[1]}
		}, ciPinsPath + ":2: " + actPath + " is not-yet-generated, and it is no workflow"},
		"a pin of a generated file": {func(root string) []ciPin {
			return append(append([]ciPin{}, pins...), ciPin{Path: genPath, Sum: sum(gen), State: pinPinned, Line: 4})
		}, ciPinsPath + ":4: pins " + genPath + ", which schema-test ci generates: delete the line"},
	} {
		root := tree()
		p, err := checkTree(root, generated, c.plant(root))
		if err != nil {
			t.Fatal(err)
		}
		if !strings.Contains(strings.Join(p, "\n"), c.says) {
			t.Errorf("%s: want %q in:\n  %s", name, c.says, strings.Join(p, "\n  "))
		}
	}
	for name, c := range map[string]struct{ line, says string }{
		"two fields":           {actPath + "\t" + sum(act), ciPinsPath + ":2: want 3 tab-separated fields"},
		"a path outside":       {"Makefile\t" + sum(act) + "\tpinned", ciPinsPath + ":2: Makefile is not under .github/"},
		"a sum that is none":   {actPath + "\tabc\tpinned", ciPinsPath + `:2: "abc" is no sha256`},
		"a state that is none": {actPath + "\t" + sum(act) + "\texempt", ciPinsPath + `:2: state "exempt" is neither`},
		"a path twice":         {actPath + "\t" + sum(act) + "\tpinned\n" + actPath + "\t" + sum(act) + "\tpinned", ciPinsPath + ":3: pins " + actPath + ", which line 2 already pins"},
	} {
		if _, p := readPins([]byte("# pins\n" + c.line + "\n")); !strings.Contains(strings.Join(p, "\n"), c.says) {
			t.Errorf("%s: want %q in %v", name, c.says, p)
		}
	}
	// the repository
	reg := loadRepoRegistry(t)
	files, err := ciFiles(reg)
	if err != nil {
		t.Fatal(err)
	}
	data, err := os.ReadFile(filepath.Join(repoRoot, ciPinsPath))
	if err != nil {
		t.Fatal(err)
	}
	repoPins, p := readPins(data)
	tp, err := checkTree(repoRoot, files, repoPins)
	if err != nil {
		t.Fatal(err)
	}
	if p = append(p, tp...); len(p) > 0 {
		t.Errorf(".github files neither generated nor pinned as they are (%d):\n  %s", len(p), strings.Join(p, "\n  "))
	}
}

// TestTheNotYetGeneratedListOnlyShrinks: against the base's ci-pins.tsv (the
// tree the change merges into), no workflow joins the not-yet-generated list
// and none leaves it as pinned; one that leaves it by being generated or
// deleted is green. A base from before ci-pins.tsv holds every workflow it
// has as not yet generated, but the generated ones and the ones that run no
// test: a list within those is green, and one naming a workflow the base
// lacks, or a generated one, is red. A base that is no directory is an
// error, never a pass. extract --since --pins-base runs it.
func TestTheNotYetGeneratedListOnlyShrinks(t *testing.T) {
	t.Parallel()
	s := strings.Repeat("a", 64)
	line := func(p, state string) string { return p + "\t" + s + "\t" + state + "\n" }
	main := "# pins\n" + line(".github/workflows/x.yml", pinNotYetGenerated) + line(".github/workflows/y.yml", pinNotYetGenerated)
	for name, c := range map[string]struct{ now, says string }{
		"one left by being generated":                   {"# pins\n" + line(".github/workflows/x.yml", pinNotYetGenerated), ""},
		"a workflow joins":                              {main + line(".github/workflows/z.yml", pinNotYetGenerated), ciPinsPath + ":4: .github/workflows/z.yml joins the not-yet-generated list, which only shrinks"},
		"a line of this tree's list that does not read": {main + ".github/workflows/z.yml\tabc\tnot-yet-generated\n", ciPinsPath + `:4: "abc" is no sha256`},
		"one leaves as pinned":                          {"# pins\n" + line(".github/workflows/x.yml", pinNotYetGenerated) + line(".github/workflows/y.yml", pinPinned), ciPinsPath + ":3: .github/workflows/y.yml leaves the not-yet-generated list as pinned"},
	} {
		since, root := t.TempDir(), t.TempDir()
		for dir, text := range map[string]string{since: main, root: c.now} {
			if err := os.MkdirAll(filepath.Join(dir, filepath.Dir(ciPinsPath)), 0o755); err != nil {
				t.Fatal(err)
			}
			if err := os.WriteFile(filepath.Join(dir, ciPinsPath), []byte(text), 0o644); err != nil {
				t.Fatal(err)
			}
		}
		p, err := pinsShrinkFrom(since, root)
		if err != nil {
			t.Fatal(err)
		}
		got := strings.Join(p, "\n")
		if c.says == "" && got != "" || c.says != "" && !strings.Contains(got, c.says) {
			t.Errorf("%s: want %q, got %q", name, c.says, got)
		}
	}
	// ci-pins.tsv deleted, while main lists not-yet-generated workflows
	if p, err := pinsShrinkFrom(func() string {
		d := t.TempDir()
		if err := os.MkdirAll(filepath.Join(d, filepath.Dir(ciPinsPath)), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(filepath.Join(d, ciPinsPath), []byte(main), 0o644); err != nil {
			t.Fatal(err)
		}
		return d
	}(), t.TempDir()); err != nil || !strings.Contains(strings.Join(p, "\n"), ciPinsPath+" is gone, and the base lists .github/workflows/x.yml") {
		t.Errorf("ci-pins.tsv deleted is not named: %v %v", p, err)
	}
	// a base from before ci-pins.tsv: its workflows are the list, but the
	// generated ones and the ones that run no test
	old := t.TempDir()
	for _, w := range []string{"x.yml", "y.yml", "ci-fast.yml", "cla.yml"} {
		if err := os.MkdirAll(filepath.Join(old, ".github", "workflows"), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(filepath.Join(old, ".github", "workflows", w), []byte("name: "+w+"\n"), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	for name, c := range map[string]struct{ now, says string }{
		"the base's workflows listed":         {main, ""},
		"fewer than the base's":               {"# pins\n" + line(".github/workflows/y.yml", pinNotYetGenerated), ""},
		"a workflow the base lacks joins":     {main + line(".github/workflows/z.yml", pinNotYetGenerated), ciPinsPath + ":4: .github/workflows/z.yml joins the not-yet-generated list"},
		"a generated workflow listed":         {main + line(fastWorkflow, pinNotYetGenerated), ciPinsPath + ":4: " + fastWorkflow + " joins the not-yet-generated list"},
		"a workflow that runs no test listed": {main + line(".github/workflows/cla.yml", pinNotYetGenerated), ciPinsPath + ":4: .github/workflows/cla.yml joins the not-yet-generated list"},
	} {
		root := t.TempDir()
		if err := os.MkdirAll(filepath.Join(root, filepath.Dir(ciPinsPath)), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(filepath.Join(root, ciPinsPath), []byte(c.now), 0o644); err != nil {
			t.Fatal(err)
		}
		p, err := pinsShrinkFrom(old, root)
		if err != nil {
			t.Fatal(err)
		}
		got := strings.Join(p, "\n")
		if c.says == "" && got != "" || c.says != "" && !strings.Contains(got, c.says) {
			t.Errorf("a base with no ci-pins.tsv, %s: want %q, got %q", name, c.says, got)
		}
	}
	// a base that is not there is an error, never a pass
	if p, err := pinsShrinkFrom(filepath.Join(old, "absent"), old); err == nil || !strings.Contains(err.Error(), "not a directory") {
		t.Errorf("a base that is not there: %v %v", p, err)
	}
}

// TestCICheckAndExtractHoldThePins: the two commands that run per pull
// request hold the pins: ci --check names an unpinned file and a pin line
// that does not read, and extract --since --pins-base names a workflow that
// joins the not-yet-generated list of the base given (not main's), and
// refuses either flag alone. Each runs in a tree of its own.
func TestCICheckAndExtractHoldThePins(t *testing.T) {
	t.Parallel()
	reg := loadRepoRegistry(t)
	files, err := ciFiles(reg)
	if err != nil {
		t.Fatal(err)
	}
	regData, err := os.ReadFile(filepath.Join(repoRoot, testreg.DefaultPath))
	if err != nil {
		t.Fatal(err)
	}
	ciTree := func(extra map[string]string) string {
		root := t.TempDir()
		all := map[string]string{testreg.DefaultPath: string(regData), ciPinsPath: "# pins\n"}
		for p, d := range files {
			all[p] = string(d)
		}
		maps.Copy(all, extra)
		for p, d := range all {
			if err := os.MkdirAll(filepath.Join(root, filepath.Dir(p)), 0o755); err != nil {
				t.Fatal(err)
			}
			if err := os.WriteFile(filepath.Join(root, p), []byte(d), 0o644); err != nil {
				t.Fatal(err)
			}
		}
		return root
	}
	var out bytes.Buffer
	if err := ciCmd([]string{"--check", "--root", ciTree(nil)}, &out); err != nil {
		t.Fatalf("a tree of only generated files: %v", err)
	}
	for name, c := range map[string]struct {
		extra map[string]string
		says  string
	}{
		"an unpinned file":              {map[string]string{".github/workflows/new.yml": "name: new\n"}, ".github/workflows/new.yml: neither generated by schema-test ci nor pinned"},
		"a pin line that does not read": {map[string]string{ciPinsPath: "# pins\n.github/x\n"}, ciPinsPath + ":2: want 3 tab-separated fields"},
	} {
		err := ciCmd([]string{"--check", "--root", ciTree(c.extra)}, io.Discard)
		if err == nil || !strings.Contains(err.Error(), c.says) {
			t.Errorf("%s: want %q, got %v", name, c.says, err)
		}
	}
	// extract --since: a workflow joins the list main holds
	main, root := extractRoot(t), extractRoot(t)
	line := func(p string) string { return p + "\t" + strings.Repeat("a", 64) + "\tnot-yet-generated\n" }
	for dir, text := range map[string]string{main: "# pins\n" + line(".github/workflows/x.yml"), root: "# pins\n" + line(".github/workflows/x.yml") + line(".github/workflows/z.yml")} {
		if err := os.WriteFile(filepath.Join(dir, ciPinsPath), []byte(text), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	out.Reset()
	err = extractCmd([]string{"--root", root, "--since", main, "--pins-base", main}, &out)
	if err == nil || !strings.Contains(out.String(), ".github/workflows/z.yml joins the not-yet-generated list") {
		t.Errorf("extract --pins-base does not name a workflow joining the list (err %v):\n%s", err, out.String())
	}
	// the list is held to the base given, not to main: main lists z, the
	// integration branch's previous tip does not, and growing the list
	// against that base is red; against a base that lists z it is green
	base := extractRoot(t)
	if err := os.WriteFile(filepath.Join(base, ciPinsPath), []byte("# pins\n"+line(".github/workflows/x.yml")), 0o644); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(main, ciPinsPath), []byte("# pins\n"+line(".github/workflows/x.yml")+line(".github/workflows/z.yml")), 0o644); err != nil {
		t.Fatal(err)
	}
	out.Reset()
	err = extractCmd([]string{"--root", root, "--since", main, "--pins-base", base}, &out)
	if err == nil || !strings.Contains(out.String(), ".github/workflows/z.yml joins the not-yet-generated list") {
		t.Errorf("growing the list against the given base is not red (err %v):\n%s", err, out.String())
	}
	out.Reset()
	if err := extractCmd([]string{"--root", root, "--since", base, "--pins-base", main}, &out); err != nil {
		t.Errorf("the list held to a base that lists every entry is red: %v\n%s", err, out.String())
	}
	if strings.Contains(out.String(), "nothing to shrink from") {
		t.Errorf("extract says the shrink check is inert:\n%s", out.String())
	}
	// ci-fast.yml runs extract with the base, from the main-tree action, on
	// every step that runs extract; a step that drops it is red
	extractSteps := func(wf string) []string {
		var bad []string
		n := 0
		for _, l := range strings.Split(wf, "\n") {
			if !strings.Contains(l, "go run ./tools/schema-test extract") {
				continue
			}
			n++
			if !strings.Contains(l, `--pins-base "$BASE_TREE"`) {
				bad = append(bad, strings.TrimSpace(l))
			}
		}
		if n == 0 {
			bad = append(bad, "no step runs extract")
		}
		if strings.Count(wf, "BASE_TREE: ${{ steps.main.outputs.base }}") != n {
			bad = append(bad, "BASE_TREE is not the main-tree action's base on every extract step")
		}
		return bad
	}
	fast := string(files[fastWorkflow])
	if bad := extractSteps(fast); len(bad) > 0 {
		t.Errorf("ci-fast.yml runs extract without the base: %v", bad)
	}
	if bad := extractSteps(strings.Replace(fast, ` --pins-base "$BASE_TREE"`, "", 1)); len(bad) == 0 {
		t.Error("PLANTED PATTERN: an extract step without --pins-base left the check green")
	}
	// --since without --pins-base, or the reverse, is refused: the base is
	// always given
	for _, args := range [][]string{{"--root", root, "--since", main}, {"--root", root, "--pins-base", main}} {
		var u usageError
		if err := extractCmd(args, io.Discard); !errors.As(err, &u) || !strings.Contains(err.Error(), "--since and --pins-base go together") {
			t.Errorf("extract %v: want the usage error, got %v", args, err)
		}
	}
}
